.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* Sidebar */
::deep .channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2c2f33;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #202225;
}

::deep .sidebar-title {
    padding: 16px;
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #8e9297;
    border-bottom: 1px solid #202225;
}

::deep .channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

::deep .channel-item {
    padding: 8px 16px;
    cursor: pointer;
    border-radius: 4px;
    margin: 0 8px;
    position: relative;
    transition: background 0.15s;
}

::deep .channel-item:hover {
    background: #36393f;
}

::deep .channel-item.active {
    background: #393c43;
    color: #fff;
}

::deep .channel-name {
    font-weight: 600;
    font-size: 0.95rem;
}

::deep .channel-description {
    font-size: 0.75rem;
    color: #8e9297;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    margin-top: 2px;
}

::deep .unread-badge {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: #ed4245;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* Message Area */
::deep .message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #36393f;
    color: #dcddde;
    min-width: 0;
}

::deep .message-area.full-width {
    flex: 1;
}

::deep .message-area.with-thread {
    flex: 0 0 55%;
}

::deep .message-area-header {
    padding: 12px 20px;
    border-bottom: 1px solid #202225;
    background: #36393f;
}

::deep .message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

::deep .message-area-header p {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #8e9297;
}

::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

::deep .loading-indicator {
    text-align: center;
    padding: 8px;
    color: #8e9297;
    font-size: 0.8rem;
}

/* Message Bubble */
::deep .message-bubble {
    padding: 8px 12px;
    border-radius: 4px;
    position: relative;
    transition: background 0.1s;
}

::deep .message-bubble:hover {
    background: #32353b;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 4px;
}

::deep .message-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.9rem;
}

::deep .message-time {
    font-size: 0.7rem;
    color: #72767d;
}

::deep .message-content {
    font-size: 0.9rem;
    line-height: 1.4;
    word-break: break-word;
}

::deep .message-reactions {
    display: flex;
    gap: 4px;
    margin-top: 6px;
    flex-wrap: wrap;
}

::deep .reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 2px 8px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 12px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background 0.15s;
}

::deep .reaction-badge:hover {
    background: #3c3f44;
    border-color: #5865f2;
}

::deep .thread-link {
    margin-top: 6px;
    font-size: 0.8rem;
    color: #5865f2;
    cursor: pointer;
    font-weight: 500;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

::deep .message-actions {
    position: absolute;
    top: -8px;
    right: 12px;
    display: flex;
    gap: 2px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 2px;
}

::deep .action-btn {
    background: none;
    border: none;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 3px;
    font-size: 0.9rem;
    transition: background 0.1s;
}

::deep .action-btn:hover {
    background: #36393f;
}

::deep .emoji-picker {
    position: absolute;
    top: -8px;
    right: 80px;
    display: flex;
    gap: 2px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 4px;
    z-index: 10;
}

::deep .emoji-btn {
    background: none;
    border: none;
    cursor: pointer;
    padding: 4px;
    border-radius: 3px;
    font-size: 1.1rem;
    transition: background 0.1s;
}

::deep .emoji-btn:hover {
    background: #36393f;
}

/* Message Input */
::deep .message-input {
    display: flex;
    gap: 8px;
    padding: 12px 20px;
    border-top: 1px solid #202225;
    background: #36393f;
}

::deep .message-input textarea {
    flex: 1;
    padding: 10px 14px;
    border: none;
    border-radius: 8px;
    background: #40444b;
    color: #dcddde;
    font-size: 0.9rem;
    resize: none;
    min-height: 40px;
    max-height: 120px;
    font-family: inherit;
    outline: none;
}

::deep .message-input textarea::placeholder {
    color: #72767d;
}

::deep .send-btn {
    padding: 8px 16px;
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 8px;
    font-weight: 600;
    font-size: 0.85rem;
    cursor: pointer;
    transition: background 0.15s;
    align-self: flex-end;
}

::deep .send-btn:hover:not(:disabled) {
    background: #4752c4;
}

::deep .send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread Panel */
::deep .thread-panel {
    width: 25%;
    min-width: 280px;
    background: #2f3136;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-left: 1px solid #202225;
}

::deep .thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
}

::deep .thread-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
}

::deep .close-btn {
    background: none;
    border: none;
    color: #8e9297;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    transition: background 0.15s, color 0.15s;
}

::deep .close-btn:hover {
    background: #36393f;
    color: #fff;
}

::deep .thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
    background: #32353b;
}

::deep .thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

